function Rename-ByPattern {
    <#
    .SYNOPSIS
      Rename the files directly in a folder whose names match a regex, using [regex]::Replace.
      Throws 'Name collision' and renames nothing if two files would get the same name or a target exists.
    #>
    [CmdletBinding(SupportsShouldProcess)]
    param(
        [Parameter(Mandatory)][string]$Path,
        [Parameter(Mandatory)][string]$Pattern,
        [Parameter(Mandatory)][AllowEmptyString()][string]$Replacement
    )
    $dir = (Resolve-Path -LiteralPath $Path).ProviderPath
    if (-not (Test-Path -LiteralPath $dir -PathType Container)) { throw "Not a folder: '$Path'" }
    $files = @(Get-ChildItem -LiteralPath $dir -File)

    $plan = [System.Collections.Generic.List[object]]::new()
    foreach ($f in $files) {
        if (-not [regex]::IsMatch($f.Name, $Pattern)) { continue }
        $new = ConvertTo-SafeFileName ([regex]::Replace($f.Name, $Pattern, $Replacement))
        if ($new -ceq $f.Name) { continue }
        $plan.Add([pscustomobject]@{ OldName = $f.Name; NewName = $new })
    }

    # Check the whole plan before touching the disk.
    $targets = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in $plan) {
        $new = $item.NewName
        if (-not $targets.Add($new)) { throw "Name collision: '$new' would be produced by more than one file" }
        if ((Test-Path -LiteralPath (Join-Path $dir $new)) -and ($new -ne $item.OldName)) {
            throw "Name collision: '$new' already exists"
        }
    }

    foreach ($item in $plan) {
        $source = Join-Path $dir $item.OldName
        if ($PSCmdlet.ShouldProcess($source, "Rename to $($item.NewName)")) {
            Rename-Item -LiteralPath $source -NewName $item.NewName
        }
        $item
    }
}

